const b = $input.first().json.body || $input.first().json;
let dias = b.dias;
if ((dias == null || dias === '' || Number(dias) === 0) && b.fecha_desde && b.fecha_hasta) {
  const d1 = new Date(b.fecha_desde), d2 = new Date(b.fecha_hasta);
  if (!isNaN(d1) && !isNaN(d2)) dias = Math.round((d2 - d1) / 86400000) + 1;
}
return [{ json: {
  id:            b.id || '',
  employee_id:   b.employee_id || '',
  clinic_id:     b.clinic_id ? String(b.clinic_id) : '',
  tipo:          b.tipo || 'vacaciones',
  fecha_desde:   b.fecha_desde || '',
  fecha_hasta:   b.fecha_hasta || '',
  dias:          dias != null ? String(dias) : '0',
  justificada:   b.justificada === true || b.justificada === 'true',
  pagada:        b.pagada === true || b.pagada === 'true',
  estado:        b.estado || 'aprobada',
  descripcion:   b.descripcion || '',
  documento_url: b.documento_url || '',
  aprobado_por:  b.aprobado_por || '',
  created_by:    b.created_by || ''
} }];
